-- FASE 2C: Vendor + Pembelian + penerimaan persediaan
create table if not exists vendors (id uuid primary key default gen_random_uuid(), organization_id uuid not null, code text not null, name text not null, contact_name text, email text, phone text, address text, is_active boolean not null default true, created_at timestamptz not null default now(), unique(organization_id,code));
create table if not exists purchases (id uuid primary key default gen_random_uuid(), organization_id uuid not null, purchase_number text not null, vendor_id uuid references vendors(id), vendor_name text not null, purchase_date date not null, due_date date, status text not null default 'DRAFT', payment_status text not null default 'UNPAID', total_amount numeric(18,2) not null default 0, paid_amount numeric(18,2) not null default 0, notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(organization_id,purchase_number));
create table if not exists purchase_items (id uuid primary key default gen_random_uuid(), purchase_id uuid not null references purchases(id) on delete cascade, product_id uuid not null, product_name text not null, quantity numeric(18,4) not null check(quantity>0), unit_cost numeric(18,2) not null check(unit_cost>=0), line_total numeric(18,2) not null);
-- Journal when purchase is received on credit: Dr Inventory / Cr Accounts Payable. Cash purchases: Cr Cash/Bank.
alter table vendors enable row level security; alter table purchases enable row level security; alter table purchase_items enable row level security;
